27: const BEGIN: &str = "*** Begin Patch";
28: const END: &str = "*** End Patch";
29: 
30: #[derive(Debug, Clone, PartialEq, Eq)]
31: enum HunkLine {
32:     Keep(String),
33:     Remove(String),
34:     Add(String),
35: }
36: 
37: #[derive(Debug, Clone, PartialEq, Eq)]
38: enum PatchOp {
39:     Add { path: String, lines: Vec<String> },
40:     Update { path: String, seq: Vec<HunkLine> },
41:     Delete { path: String },
42: }
43: 
44: pub struct ApplyPatch {
45:     spec: ToolSpec,
46: }
