54: impl ApplyPatch {
55:     pub fn new() -> Self {
56:         Self {
57:             spec: ToolSpec::new(
58:                 "apply_patch",
59:                 "对工作区文件应用结构化补丁（V4A 格式：Add/Update/Delete File）。上下文先精确匹配，失败时依次尝试剥离行号前缀、缩进弹性、空白折叠、首尾锚点模糊定位；整单失败自动回滚。",
60:                 serde_json::json!({
61:                     "type": "object",
62:                     "properties": {
63:                         "patch": {
64:                             "type": "string",
65:                             "description": "以 *** Begin Patch 开头、*** End Patch 结尾的补丁文本"
66:                         }
67:                     },
68:                     "required": ["patch"]
69:                 }),
70:             ),
71:         }
72:     }
73: }
