77: fn parse_patch(patch: &str) -> Result<Vec<PatchOp>, ToolError> {
78:     let trimmed = patch.trim_start();
79:     if !trimmed.starts_with(BEGIN) {
80:         return Err(ToolError::InvalidArgs(
81:             "补丁必须以 *** Begin Patch 开头".into(),
82:         ));
83:     }
84:     let body = &trimmed[BEGIN.len()..];
85:     let body = body.strip_prefix('\n').unwrap_or(body);
86:     let lines: Vec<&str> = body.lines().collect();
87: 
88:     let mut ops: Vec<PatchOp> = Vec::new();
89:     let mut i = 0usize;
90:     while i < lines.len() {
91:         let line = lines[i];
92:         if line.trim() == END {
93:             break;
94:         }
95:         if let Some(path) = line.strip_prefix("*** Add File: ") {
96:             i += 1;
97:             let mut content = Vec::new();
98:             while i < lines.len() {
99:                 let l = lines[i];
100:                 if l.starts_with("*** ") {
101:                     break;
102:                 }
103:                 let Some(rest) = l.strip_prefix('+') else {
104:                     return Err(ToolError::InvalidArgs(format!(
105:                         "Add File 段的行必须以 + 开头: {l:?}"
106:                     )));
107:                 };
108:                 content.push(rest.to_string());
109:                 i += 1;
110:             }
111:             ops.push(PatchOp::Add { path: path.trim().to_string(), lines: content });
112:         } else if let Some(path) = line.strip_prefix("*** Update File: ") {
113:             i += 1;
114:             let mut seq: Vec<HunkLine> = Vec::new();
115:             while i < lines.len() && !lines[i].starts_with("*** ") {
116:                 let l = lines[i];
117:                 if l == "@@" {
118:                     i += 1;
119:                     continue; // 分组标记在连续匹配语义下不改变序列
120:                 }

