398: // ============================== 写前读状态（SH-124） ==============================
399: 
400: const STALE_EXCERPT_LINES: usize = 80;
401: /// 回填给模型的上限（字节）。几 MB 的文件全文回填会直接吃光上下文，
402: /// 而模型重建补丁只需要一处接缝附近的真实内容——字节上限与行数上限同时生效，
403: /// 取先到者（SH-126③）。
404: const STALE_EXCERPT_BYTES: usize = 8 * 1024;
405: 
406: /// 冲突回填：给出文件当前内容（带行号，行数 + 字节双上限截断），让模型基于真实内容重建补丁。
407: fn current_excerpt(bytes: &[u8]) -> String {
408:     let text = String::from_utf8_lossy(bytes);
409:     let mut out = String::new();
410:     let mut truncated = false;
411:     for (idx, line) in text.lines().enumerate() {
412:         // 逐行累加：按整行截断才不会切断 UTF-8 边界。
413:         if idx >= STALE_EXCERPT_LINES || out.len() + line.len() + 8 > STALE_EXCERPT_BYTES {
414:             truncated = true;
415:             break;
416:         }
417:         if !out.is_empty() {
418:             out.push('\n');
419:         }
420:         out.push_str(&format!("{}| {line}", idx + 1));
421:     }
422:     if truncated {
423:         out.push_str(&format!(
424:             "\n…（已截断：最多回填前 {STALE_EXCERPT_LINES} 行 / {STALE_EXCERPT_BYTES} 字节）"
425:         ));
426:     }
427:     out
428: }
429: 
430: /// 写前校验：必须先读过（同会话 + 同路径），且内容没被外部改过。
431: /// 返回用于写后刷新登记表的路径键（None = 未启用登记表）。
432: fn verify_read_state(
433:     ctx: &ToolContext,
434:     path: &str,
435:     full: &std::path::Path,
436:     current: &[u8],
437: ) -> Result<Option<std::path::PathBuf>, ToolError> {
438:     let Some(reads) = &ctx.reads else { return Ok(None) };
439:     let key = crate::tool_router::canonical_key(full);
440:     let Some(recorded) = reads.get(ctx.session_id.as_deref(), &key) else {
441:         return Ok(None);
442:     };
443:     let meta = std::fs::metadata(full)
444:         .map_err(|e| ToolError::Execution(format!("读取失败: {e}")))?;
445:     if !crate::tool_router::content_matches(&recorded, current, &meta) {
446:         return Err(ToolError::Execution(format!(
447:             "write_file_stale: {path} 在读取后被外部修改，已拒绝覆盖（本轮未写入该文件）。当前文件内容：\n{}",
448:             current_excerpt(current)
449:         )));
450:     }
451:     Ok(Some(key))
452: }
453: 
454: /// 写成功后刷新登记表：模型自此持有的是文件最新内容。
455: fn refresh_read_state(ctx: &ToolContext, key: Option<std::path::PathBuf>, full: &std::path::Path) {
456:     let (Some(reads), Some(key)) = (&ctx.reads, key) else { return };
457:     if let Ok(stamp) = crate::tool_router::FileStamp::of_full_file(full) {
458:         reads.record(ctx.session_id.as_deref(), &key, stamp);
459:     }
460: }
461: 
462: /// 把本次写入登记进写日志（SH-126）：自愈闭环据此判断「是否靠改测试变绿」。
463: fn record_write(ctx: &ToolContext, full: &std::path::Path, before: Option<&str>, after: Option<&str>) {
464:     if let Some(writes) = &ctx.writes {
465:         writes.record(full, before, after);
466:     }
467: }
468: 
469: /// 回滚结果：`restored` 已改回，`failed` 未能改回（`路径: 原因`）。
470: /// 路径排序，保证错误文案稳定、可断言。
471: #[derive(Default)]
472: struct RollbackReport {
473:     restored: Vec<String>,
474:     failed: Vec<String>,
475: }
476: 
477: /// 把快照里的文件写回原状（`None` = 原本不存在，回滚即删除）。
478: fn rollback(snapshot: &HashMap<String, Option<Vec<u8>>>) -> RollbackReport {
479:     let mut report = RollbackReport::default();
480:     let mut paths: Vec<&String> = snapshot.keys().collect();
481:     paths.sort();
482:     for path in paths {
483:         let result = match &snapshot[path] {
484:             Some(bytes) => std::fs::write(path, bytes),
485:             None => std::fs::remove_file(path),
486:         };
487:         match result {
488:             Ok(()) => report.restored.push(path.clone()),
489:             Err(error) => report.failed.push(format!("{path}: {error}")),
490:         }
491:     }
492:     report
493: }
494: 
495: /// 把回滚结果附在原始错误后面。
496: ///
497: /// 全部改回成功 → 原样返回：正常失败路径（回滚成功）的文案仍是「写入失败: x」一句话，
498: /// 不拿回滚细节污染它。
499: ///
500: /// 有文件没改回 → 单列两份清单。多文件补丁中途失败且回滚也失败时，工作区停在半修改
501: /// 状态；只说「写入失败: {path}」会让模型误以为什么都没变，按错误前提继续下一步。
502: fn with_rollback(error: ToolError, report: RollbackReport) -> ToolError {
503:     if report.failed.is_empty() {
504:         return error;
505:     }
506:     let restored = if report.restored.is_empty() {
507:         String::new()
508:     } else {
509:         format!("（{}）", report.restored.join("、"))
510:     };
511:     ToolError::Execution(format!(
512:         "{error}；回滚未完成：已改回 {} 个文件{restored}，未能改回 {} 个文件 [{}]。\
513:          工作区停在半修改状态——请先检查这些文件，不要按「什么都没变」继续",
514:         report.restored.len(),
515:         report.failed.len(),
516:         report.failed.join("；"),
517:     ))
518: }
